"""Names shared across the integration and the panel it serves."""

DOMAIN = "tsvk_scheduler"

# The one generated automation that does the switching. Its `variables` block is also
# where the rule set lives, so automations.yaml is the only persistent store.
ENGINE_ID = "tsvk_scheduler_engine"
ENGINE_ALIAS = "TSVK Scheduler — engine"
ENGINE_DESCRIPTION = (
    "Generated by the Schedules panel. Do not edit here — "
    "changes are overwritten on the next save."
)

# Firing this re-asserts every scheduled device to what its schedule says right now.
APPLY_EVENT = "tsvk_scheduler_apply"

# Hidden dashboard holding a read-only copy of the model. Home Assistant refuses
# /api/config/* to non-admins, so this is the only place they can read it from.
MIRROR_PATH = "tsvk-schedules-data"
MIRROR_TITLE = "Schedules (data)"
MIRROR_NOTE = (
    "Read-only mirror of the Schedules panel model, written automatically so non-admin "
    "users can view schedules. Home Assistant refuses `/api/config/*` to non-admins, "
    "which is where the real model lives. Do not edit by hand."
)

# Sidebar panel.
PANEL_URL_PATH = "tsvk-schedules"
PANEL_TITLE = "Schedules"
PANEL_ICON = "mdi:calendar-clock"
PANEL_ELEMENT = "tsvk-scheduler-panel"
PANEL_FILENAME = "tsvk-scheduler-panel.js"
FRONTEND_URL_BASE = "/tsvk_scheduler_frontend"

STORAGE_KEY = f"{DOMAIN}.auth"
STORAGE_VERSION = 1
SYSTEM_USER_NAME = "TSVK Scheduler"

DAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]

# Mirrors SCHEDULABLE in the panel. Anything outside this cannot be scheduled, which
# also stops a caller pointing a rule at something surprising.
ALLOWED_DOMAINS = {
    "switch",
    "light",
    "input_boolean",
    "fan",
    "siren",
    "valve",
    "humidifier",
    "automation",
}
